test("three courses weight to 3.125 and round half to even to 3.12", function () {
  var actual = code.calculateGpa({
    courses: [
      { gradePoints: "3.7", credits: "3" },
      { gradePoints: "3.3", credits: "3" },
      { gradePoints: "2.0", credits: "2" }
    ]
  });
  assert.deepEqual(actual, { gpa: "3.12" });
});

test("four one-credit courses weight to 2.675 and round half to even to 2.68", function () {
  var actual = code.calculateGpa({
    courses: [
      { gradePoints: "4.0", credits: "1" },
      { gradePoints: "3.0", credits: "1" },
      { gradePoints: "2.0", credits: "1" },
      { gradePoints: "1.7", credits: "1" }
    ]
  });
  assert.deepEqual(actual, { gpa: "2.68" });
});

test("empty courses return no gpa", function () {
  var actual = code.calculateGpa({ courses: [] });
  assert.deepEqual(actual, { gpa: null });
});

test("a single course with zero credits returns no gpa", function () {
  var actual = code.calculateGpa({
    courses: [{ gradePoints: "4.0", credits: "0" }]
  });
  assert.deepEqual(actual, { gpa: null });
});

test("one course of one credit returns that grade with two decimals", function () {
  var actual = code.calculateGpa({
    courses: [{ gradePoints: "3", credits: "1" }]
  });
  assert.deepEqual(actual, { gpa: "3.00" });
});

test("integer and one-decimal grade strings in one case average to 3.00", function () {
  var actual = code.calculateGpa({
    courses: [
      { gradePoints: "3", credits: "2" },
      { gradePoints: "3.0", credits: "1" }
    ]
  });
  assert.deepEqual(actual, { gpa: "3.00" });
});

test("1.225 rounds half to even down to 1.22", function () {
  var actual = code.calculateGpa({
    courses: [{ gradePoints: "1.225", credits: "1" }]
  });
  assert.deepEqual(actual, { gpa: "1.22" });
});

test("1.005 rounds half to even to 1.00", function () {
  var actual = code.calculateGpa({
    courses: [{ gradePoints: "1.005", credits: "1" }]
  });
  assert.deepEqual(actual, { gpa: "1.00" });
});

test("rounding is applied only to the final quotient", function () {
  var actual = code.calculateGpa({
    courses: [
      { gradePoints: "2.005", credits: "3" },
      { gradePoints: "1", credits: "1" }
    ]
  });
  assert.deepEqual(actual, { gpa: "1.75" });
});

test("a quotient just below 3.125 stays 3.12", function () {
  var actual = code.calculateGpa({
    courses: [
      { gradePoints: "3.7", credits: "3" },
      { gradePoints: "3.3", credits: "3" },
      { gradePoints: "1.999", credits: "2" }
    ]
  });
  assert.deepEqual(actual, { gpa: "3.12" });
});

test("a quotient just above 3.125 rounds to 3.13", function () {
  var actual = code.calculateGpa({
    courses: [
      { gradePoints: "3.7", credits: "3" },
      { gradePoints: "3.3", credits: "3" },
      { gradePoints: "2.001", credits: "2" }
    ]
  });
  assert.deepEqual(actual, { gpa: "3.13" });
});

test("a value just below 2.675 rounds to 2.67", function () {
  var actual = code.calculateGpa({
    courses: [{ gradePoints: "2.6749", credits: "1" }]
  });
  assert.deepEqual(actual, { gpa: "2.67" });
});

test("a value just above 2.675 rounds to 2.68", function () {
  var actual = code.calculateGpa({
    courses: [{ gradePoints: "2.6751", credits: "1" }]
  });
  assert.deepEqual(actual, { gpa: "2.68" });
});

test("a zero-credit course first still yields 2.50", function () {
  var actual = code.calculateGpa({
    courses: [
      { gradePoints: "9.9", credits: "0" },
      { gradePoints: "4", credits: "1" },
      { gradePoints: "2.0", credits: "3" }
    ]
  });
  assert.deepEqual(actual, { gpa: "2.50" });
});

test("a zero-credit course in the middle still yields 2.50", function () {
  var actual = code.calculateGpa({
    courses: [
      { gradePoints: "4", credits: "1" },
      { gradePoints: "9.9", credits: "0" },
      { gradePoints: "2.0", credits: "3" }
    ]
  });
  assert.deepEqual(actual, { gpa: "2.50" });
});

test("a zero-credit course last still yields 2.50", function () {
  var actual = code.calculateGpa({
    courses: [
      { gradePoints: "4", credits: "1" },
      { gradePoints: "2.0", credits: "3" },
      { gradePoints: "9.9", credits: "0" }
    ]
  });
  assert.deepEqual(actual, { gpa: "2.50" });
});
